2	/*
3	 * Quest for Quantum
4	 * =================
5	 * core/event_bus.h
6	 *
7	 * A lightweight, thread-aware event bus that powers the entire simulation.
8	 * Every module (input, scripting, physics, AI, audio, etc.) communicates by
9	 * publishing or subscribing to events that flow through this central hub.
10	 *
11	 * This header is “header-only”—define Q4Q_EVENT_BUS_IMPLEMENTATION in exactly
12	 * ONE .c or .cpp translation unit before including this file to generate the
13	 * implementation.
14	 *
15	 * Example:
16	 *
17	 *      #define Q4Q_EVENT_BUS_IMPLEMENTATION
18	 *      #include "core/event_bus.h"
19	 *
20	 * Compile with ‑pthread (or platform equivalent) if
21	 * Q4Q_EVENT_BUS_THREAD_SAFE is defined.
22	 */
23	
24	#ifndef Q4Q_EVENT_BUS_H
25	#define Q4Q_EVENT_BUS_H
26	
27	/* ------------------------------------------------------------------------- */
28	/* Public configuration macros                                               */
29	/* ------------------------------------------------------------------------- */
30	
31	/*
32	 * Define Q4Q_EVENT_BUS_THREAD_SAFE to make the bus internally synchronized.
33	 * The implementation uses pthreads on POSIX and falls back to a dummy lock
34	 * when not available.
35	 */
36	#ifndef Q4Q_EVENT_BUS_THREAD_SAFE
37	#   define Q4Q_EVENT_BUS_THREAD_SAFE 1
38	#endif
39	
40	/* Maximum distinct event types the bus will manage. */
41	#ifndef Q4Q_EVENT_BUS_MAX_EVENT_TYPES
42	#   define Q4Q_EVENT_BUS_MAX_EVENT_TYPES 256
43	#endif
44	
45	/* ------------------------------------------------------------------------- */
46	/* Public API                                                                */
47	/* ------------------------------------------------------------------------- */
48	
49	#include <stdint.h>
50	#include <stddef.h>
51	#include <stdbool.h>
52	#include <time.h>
53	
54	#ifdef __cplusplus
55	extern "C" {
56	#endif
57	
58	/*
59	 * Event type IDs are user-defined integers. 0 is reserved for “invalid”.
60	 * In practice, keep a central enum shared between modules:
61	 *
62	 *      typedef enum {
63	 *          EVT_INVALID = 0,
64	 *          EVT_KEYBOARD,
65	 *          EVT_COLLISION,
66	 *          ...
67	 *      } q4q_event_type_e;
68	 */
69	typedef uint32_t q4q_event_type_t;
70	
71	/* Opaque subscription handle returned by q4q_event_bus_subscribe(). */
72	typedef int32_t  q4q_listener_id_t;
73	
74	/*
75	 * Payload wrapper.
76	 * For small, POD-style payloads (< sizeof(void*) * 2), pass by value using
77	 * the “inline” union below.  For larger or dynamically shaped payloads,
78	 * allocate externally and store only a pointer/size pair.
79	 */
80	typedef struct q4q_event_payload_s {
81	    const void *bytes;
82	    size_t      size;
83	} q4q_event_payload_t;
84	
85	/*
86	 * Event object. Users are encouraged to stack-allocate and zero-init.
87	 */
88	typedef struct q4q_event_s {
89	    q4q_event_type_t    type;
90	    void               *sender;     /* Optional pointer to the originator. */
91	    uint64_t            timestamp;  /* Nanoseconds since unix epoch.        */
92	
93	    /* Inline “small” payload (16 bytes) avoids heap churn for tiny events. */
94	    union {
95	        uint8_t  u8 [16];
96	        uint16_t u16[ 8];
97	        uint32_t u32[ 4];
98	        uint64_t u64[ 2];
99	        float    f32[ 4];
100	        double   f64[ 2];
101	    } small;
102	
103	    /* Extended payload, if any. */
104	    q4q_event_payload_t extra;
105	} q4q_event_t;
106	
107	/*
108	 * Listener signature: `event` is read-only, `user_data` is the opaque context
109	 * supplied during subscription.
110	 */
111	typedef void (*q4q_event_listener_f)(
112	        const q4q_event_t *event, void *user_data);
113	
114	
115	/* ---------- Lifecycle --------------------------------------------------- */
116	
117	/*
118	 * Initialise / shutdown the global bus instance.
119	 * The bus is a singleton; calling `init` more than once is a no-op.
120	 * Return true on success, false on allocation or system failure.
121	 */
122	bool q4q_event_bus_init  (void);
123	void q4q_event_bus_shutdown(void);
124	
125	/* ---------- Subscription ------------------------------------------------ */
126	
127	/*
128	 * Subscribe a callback to a particular event type.
129	 *
130	 *  - `event_type`  : Which event to listen for.
131	 *  - `listener_fn` : Function pointer to be invoked on dispatch.
132	 *  - `user_data`   : Opaque context pointer passed back on every call.
133	 *
134	 * Returns a positive listener ID (>=0) on success. Negative values indicate
135	 * an error: -1 = bus not initialised, -2 = invalid args, -3 = out of memory,
136	 * -4 = exceeded max listeners.
137	 */
138	q4q_listener_id_t
139	q4q_event_bus_subscribe(q4q_event_type_t     event_type,
140	                        q4q_event_listener_f listener_fn,
141	                        void                *user_data);
142	
143	/*
144	 * Unsubscribe a previously registered listener.
145	 * Silently ignores unknown `listener_id`s.
146	 */
147	void
148	q4q_event_bus_unsubscribe(q4q_event_type_t event_type,
149	                          q4q_listener_id_t listener_id);
150	
151	/* ---------- Publish ----------------------------------------------------- */
152	
153	/*
154	 * Publish an event to every listener subscribed to `event->type`.
155	 * The function copies the struct by value, so the caller retains ownership
156	 * of any external memory referenced by `extra.bytes`.
157	 */
158	void
159	q4q_event_bus_publish(const q4q_event_t *event);
