163	#ifdef __cplusplus
164	} /* extern "C" */
165	#endif
166	
167	/* ========================================================================= */
168	/* Implementation                                                            */
169	/* ========================================================================= */
170	#ifdef Q4Q_EVENT_BUS_IMPLEMENTATION
171	
172	/* -------------------- Internal structures -------------------------------- */
173	
174	#include <stdlib.h>
175	#include <string.h>
176	
177	#if Q4Q_EVENT_BUS_THREAD_SAFE
178	#   include <pthread.h>
179	#endif
180	
181	typedef struct q4q_listener_node_s {
182	    q4q_event_listener_f cb;
183	    void                *user_data;
184	    q4q_listener_id_t    id;
185	    struct q4q_listener_node_s *next;
186	} q4q_listener_node_t;
187	
188	typedef struct {
189	    q4q_listener_node_t *head;
190	} q4q_listener_list_t;
191	
192	static struct {
193	    bool                 initialised;
194	    q4q_listener_id_t    next_id;
195	    q4q_listener_list_t  lists[Q4Q_EVENT_BUS_MAX_EVENT_TYPES];
196	
197	#if Q4Q_EVENT_BUS_THREAD_SAFE
198	    pthread_mutex_t      lock;
199	#endif
200	} g_bus;
201	
202	/* -------------------- Utility helpers ----------------------------------- */
203	
204	static inline uint64_t
205	q4q_now_nsec(void)
206	{
207	    struct timespec ts;
208	#if defined(CLOCK_MONOTONIC_RAW)
209	    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
210	#else
211	    clock_gettime(CLOCK_REALTIME, &ts);
212	#endif
213	    return (uint64_t)ts.tv_sec * 1000000000ull + (uint64_t)ts.tv_nsec;
214	}
215	
216	static void
217	q4q_bus_lock(void)
218	{
219	#if Q4Q_EVENT_BUS_THREAD_SAFE
220	    pthread_mutex_lock(&g_bus.lock);
221	#endif
222	}
223	
224	static void
225	q4q_bus_unlock(void)
226	{
227	#if Q4Q_EVENT_BUS_THREAD_SAFE
228	    pthread_mutex_unlock(&g_bus.lock);
229	#endif
230	}
231	
232	/* -------------------- Public API implementation ------------------------- */
233	
234	bool
235	q4q_event_bus_init(void)
236	{
237	    if (g_bus.initialised)
238	        return true;
239	
240	    memset(&g_bus, 0, sizeof(g_bus));
241	
242	#if Q4Q_EVENT_BUS_THREAD_SAFE
243	    if (pthread_mutex_init(&g_bus.lock, NULL) != 0)
244	        return false;
245	#endif
246	
247	    g_bus.initialised = true;
248	    g_bus.next_id     = 0;
249	    return true;
250	}
251	
252	void
253	q4q_event_bus_shutdown(void)
254	{
255	    if (!g_bus.initialised)
256	        return;
257	
258	    q4q_bus_lock();
259	
260	    /* Free all listener nodes */
261	    for (size_t i = 0; i < Q4Q_EVENT_BUS_MAX_EVENT_TYPES; ++i) {
262	        q4q_listener_node_t *node = g_bus.lists[i].head;
263	        while (node) {
264	            q4q_listener_node_t *next = node->next;
265	            free(node);
266	            node = next;
267	        }
268	        g_bus.lists[i].head = NULL;
269	    }
270	
271	    g_bus.initialised = false;
272	
273	    q4q_bus_unlock();
274	
275	#if Q4Q_EVENT_BUS_THREAD_SAFE
276	    pthread_mutex_destroy(&g_bus.lock);
277	#endif
278	}
279	
280	q4q_listener_id_t
281	q4q_event_bus_subscribe(q4q_event_type_t      event_type,
282	                        q4q_event_listener_f  listener_fn,
283	                        void                 *user_data)
284	{
285	    if (!g_bus.initialised)
286	        return -1;
287	    if (event_type >= Q4Q_EVENT_BUS_MAX_EVENT_TYPES || listener_fn == NULL)
288	        return -2;
289	
290	    q4q_listener_node_t *node = (q4q_listener_node_t *)
291	                                 malloc(sizeof(q4q_listener_node_t));
292	    if (!node)
293	        return -3;
294	
295	    node->cb        = listener_fn;
296	    node->user_data = user_data;
297	
298	    q4q_bus_lock();
299	
300	    node->id   = g_bus.next_id++;
301	    node->next = g_bus.lists[event_type].head;
302	    g_bus.lists[event_type].head = node;
303	
304	    q4q_bus_unlock();
305	
306	    return node->id;
307	}
308	
309	void
310	q4q_event_bus_unsubscribe(q4q_event_type_t event_type,
311	                          q4q_listener_id_t listener_id)
312	{
313	    if (!g_bus.initialised)
314	        return;
315	    if (event_type >= Q4Q_EVENT_BUS_MAX_EVENT_TYPES)
316	        return;
317	
318	    q4q_bus_lock();
319	
320	    q4q_listener_node_t **pp = &g_bus.lists[event_type].head;
321	    while (*pp) {
322	        q4q_listener_node_t *node = *pp;
323	        if (node->id == listener_id) {
324	            *pp = node->next;
325	            free(node);
326	            break;
327	        }
328	        pp = &node->next;
329	    }
330	
331	    q4q_bus_unlock();
332	}
333	
334	void
335	q4q_event_bus_publish(const q4q_event_t *event)
336	{
337	    if (!event || !g_bus.initialised)
338	        return;
339	    if (event->type >= Q4Q_EVENT_BUS_MAX_EVENT_TYPES)
340	        return;
341	
342	    /* Take snapshot of time if caller forgot. */
343	    q4q_event_t local = *event;
344	    if (local.timestamp == 0)
345	        local.timestamp = q4q_now_nsec();
346	
347	    q4q_bus_lock();
348	
349	    /* Copy pointer because callback may mutate list. */
350	    q4q_listener_node_t *node = g_bus.lists[local.type].head;
351	
352	    /* Increment ref counts if necessary (not needed for linked list). */
353	    while (node) {
354	        /* The callback can unsubscribe itself; so we copy next first. */
355	        q4q_listener_node_t *next = node->next;
356	        node->cb(&local, node->user_data);
357	        node = next;
358	    }
359	
360	    q4q_bus_unlock();
361	}
362	
363	#endif /* Q4Q_EVENT_BUS_IMPLEMENTATION */
364	#endif /* Q4Q_EVENT_BUS_H */
