228	/* --------------------------------------------------------------------------
229	   Utility : memory allocation with checked failure
230	   -------------------------------------------------------------------------- */
231	static void *ecs_checked_alloc(size_t size)
232	{
233	    void *p = malloc(size);
234	    if(!p)
235	    {
236	        fprintf(stderr, "[ecs] Out of memory (%zu bytes)\n", size);
237	        abort();
238	    }
239	    return p;
240	}
241	
242	static void *ecs_checked_realloc(void *ptr, size_t size)
243	{
244	    void *p = realloc(ptr, size);
245	    if(!p)
246	    {
247	        fprintf(stderr, "[ecs] Out of memory (realloc %zu bytes)\n", size);
248	        abort();
249	    }
250	    return p;
251	}
