253	/* --------------------------------------------------------------------------
254	   Internal : world grow
255	   -------------------------------------------------------------------------- */
256	static void ecs_world_grow(ecs_world *world, uint32_t new_capacity)
257	{
258	    assert(new_capacity > world->capacity);
259	
260	    world->generations     = ecs_checked_realloc(world->generations,
261	                              new_capacity * sizeof(world->generations[0]));
262	    world->component_masks = ecs_checked_realloc(world->component_masks,
263	                              new_capacity * sizeof(world->component_masks[0]));
264	
265	    for(uint32_t i = world->capacity; i < new_capacity; ++i)
266	    {
267	        world->generations[i]     = 0u;
268	        world->component_masks[i] = 0u;
269	    }
270	
271	    /* Grow each registered component pool */
272	    for(uint32_t cid = 0; cid < world->component_count; ++cid)
273	    {
274	        component_pool_t *pool = &world->components[cid];
275	        size_t old_bytes = (size_t)world->capacity * pool->element_size;
276	        size_t new_bytes = (size_t)new_capacity    * pool->element_size;
277	        pool->data = ecs_checked_realloc(pool->data, new_bytes);
278	        /* Zero initialised the new slice */
279	        memset(pool->data + old_bytes, 0, new_bytes - old_bytes);
280	    }
281	
282	    world->capacity = new_capacity;
283	}
