291	    memset(world, 0, sizeof(*world));
292	
293	    world->capacity       = ECS_STARTING_CAPACITY;
294	    world->generations    = (uint32_t*)ecs_checked_alloc(world->capacity * sizeof(uint32_t));
295	    world->component_masks= (uint64_t*)ecs_checked_alloc(world->capacity * sizeof(uint64_t));
296	
297	    memset(world->generations,     0, world->capacity * sizeof(uint32_t));
298	    memset(world->component_masks, 0, world->capacity * sizeof(uint64_t));
299	
300	    /* Systems collection (start small) */
301	    world->system_capacity = 8u;
302	    world->systems = (ecs_system_t*)ecs_checked_alloc(world->system_capacity * sizeof(ecs_system_t));
303	    memset(world->systems, 0, world->system_capacity * sizeof(ecs_system_t));
304	
