308	void ecs_world_destroy(ecs_world *world)
309	{
310	    if(!world) return;
311	
312	    /* Destruct all components of living entities */
313	    for(uint32_t index = 0; index < world->capacity; ++index)
314	    {
315	        if(world->component_masks[index] == 0) continue;
316	        for(uint32_t cid = 0; cid < world->component_count; ++cid)
317	        {
318	            if(world->component_masks[index] & (1ull << cid))
319	            {
320	                component_pool_t *pool = &world->components[cid];
321	                if(pool->dtor)
322	                {
323	                    void *ptr = pool->data + (size_t)index * pool->element_size;
324	                    pool->dtor(ptr);
325	                }
326	            }
327	        }
328	    }
329	
330	    /* Free component pools */
331	    for(uint32_t cid = 0; cid < world->component_count; ++cid)
332	    {
333	        free(world->components[cid].data);
334	    }
335	
336	    free(world->systems);
337	    free(world->generations);
338	    free(world->component_masks);
339	    free(world);
340	}
