343	   Entity management
344	   -------------------------------------------------------------------------- */
345	ecs_entity_t ecs_entity_create(ecs_world *world)
346	{
347	    assert(world);
348	
349	    /* Search for a free slot                                                 */
350	    uint32_t index = world->entity_count;
351	    if(index >= world->capacity)   /* Need to grow                            */
352	        ecs_world_grow(world, world->capacity * 2);
353	
354	    /* Invariant: world->component_masks[index] == 0                          */
355	    /* Guarantee by ecs_entity_destroy                                        */
356	    while(world->component_masks[index] != 0)
357	    {
358	        ++index;
359	        if(index >= world->capacity)
360	            ecs_world_grow(world, world->capacity * 2);
361	    }
362	
363	    world->entity_count = index + 1;           /* may extend count           */
364	    uint32_t gen = world->generations[index];
365	
366	    return (ecs_entity_t)((gen << ECS_ENTITY_GENERATION_SHIFT) | index);
367	}
