369	bool ecs_entity_destroy(ecs_world *world, ecs_entity_t e)
370	{
371	    uint32_t index = ecs_entity_index(e);
372	    uint32_t gen   = ecs_entity_generation(e);
373	
374	    if(index >= world->capacity) return false;
375	    if(world->generations[index] != gen) return false; /* stale handle */
376	
377	    /* Call destructors on components                                         */
378	    uint64_t mask = world->component_masks[index];
379	    for(uint32_t cid = 0; cid < world->component_count; ++cid)
380	    {
381	        if(mask & (1ull << cid))
382	        {
383	            component_pool_t *pool = &world->components[cid];
384	            if(pool->dtor)
385	            {
386	                void *ptr = pool->data + (size_t)index * pool->element_size;
387	                pool->dtor(ptr);
388	            }
389	        }
390	    }
391	
392	    world->component_masks[index] = 0u;
393	    world->generations[index]     = (world->generations[index] + 1u) & ECS_ENTITY_GENERATION_MASK;
394	
395	    /* Optional: shrink entity_count trailing empty indices */
396	    if(index + 1 == world->entity_count)
397	    {
398	        while(world->entity_count > 0 &&
399	              world->component_masks[world->entity_count - 1] == 0)
400	        {
401	            --world->entity_count;
402	        }
403	    }
404	
405	    return true;
406	}
