453	void *ecs_component_add(ecs_world *world, ecs_entity_t e, ecs_component_id_t cid)
454	{
455	    uint32_t index = ecs_entity_index(e);
456	    uint32_t gen   = ecs_entity_generation(e);
457	    if(index >= world->capacity) return NULL;
458	    if(world->generations[index] != gen) return NULL;
459	
460	    component_pool_t *pool = &world->components[cid];
461	    if(world->component_masks[index] & (1ull << cid))
462	        return pool->data + (size_t)index * pool->element_size; /* already exists */
463	
464	    /* Add the component                                                      */
465	    world->component_masks[index] |= (1ull << cid);
466	
467	    void *ptr = pool->data + (size_t)index * pool->element_size;
468	    memset(ptr, 0, pool->element_size);
469	
470	    if(pool->ctor)
471	        pool->ctor(ptr);
472	
473	    return ptr;
474	}
