520	static void ecs_world_grow_systems(ecs_world *world)
521	{
522	    uint32_t new_capacity = world->system_capacity * 2u;
523	    world->systems = (ecs_system_t*)ecs_checked_realloc(world->systems,
524	                    new_capacity * sizeof(ecs_system_t));
525	    memset(world->systems + world->system_capacity, 0,
526	           (new_capacity - world->system_capacity) * sizeof(ecs_system_t));
527	    world->system_capacity = new_capacity;
