545	/* --------------------------------------------------------------------------
546	   Tick
547	   -------------------------------------------------------------------------- */
548	void ecs_world_tick(ecs_world *world, float dt)
549	{
550	    /* For each system, gather matching entities                               */
551	    for(uint32_t s = 0; s < world->system_count; ++s)
552	    {
553	        ecs_system_t *sys = &world->systems[s];
554	
555	        /* Collect entities into stack array first (reasonable assumption) */
556	        const uint32_t STACK_MAX = 256;
557	        ecs_entity_t stack_buf[STACK_MAX];
558	        ecs_entity_t *dynamic_buf = NULL;
559	        ecs_entity_t *list = stack_buf;
560	        size_t count = 0, capacity = STACK_MAX;
561	
562	        for(uint32_t index = 0; index < world->entity_count; ++index)
563	        {
564	            uint64_t mask = world->component_masks[index];
565	            if((mask & sys->mask) == sys->mask && mask != 0)
566	            {
567	                if(count == capacity)
568	                {
569	                    /* Move to dynamic buffer                                    */
570	                    capacity *= 2;
571	                    if(list == stack_buf)
572	                    {
573	                        dynamic_buf = (ecs_entity_t*)ecs_checked_alloc(capacity * sizeof(ecs_entity_t));
574	                        memcpy(dynamic_buf, stack_buf, count * sizeof(ecs_entity_t));
575	                    }
576	                    else
577	                    {
578	                        dynamic_buf = (ecs_entity_t*)ecs_checked_realloc(dynamic_buf,
579	                                    capacity * sizeof(ecs_entity_t));
580	                    }
581	                    list = dynamic_buf;
582	                }
583	                uint32_t gen = world->generations[index];
584	                list[count++] = (ecs_entity_t)((gen << ECS_ENTITY_GENERATION_SHIFT) | index);
585	            }
586	        }
587	
588	        if(count > 0)
589	            sys->update(world, dt, list, count, sys->user_data);
590	
591	        if(dynamic_buf)
592	            free(dynamic_buf);
593	    }
594	}
