61	static vec3_t check_vec3(lua_State *L, int idx)
62	{
63	    vec3_t v = {0.0, 0.0, 0.0};
64	
65	    if (lua_istable(L, idx))
66	    {
67	        lua_getfield(L, idx, "x");
68	        v.x = luaL_optnumber(L, -1, 0.0);
69	        lua_pop(L, 1);
70	
71	        lua_getfield(L, idx, "y");
72	        v.y = luaL_optnumber(L, -1, 0.0);
73	        lua_pop(L, 1);
74	
75	        lua_getfield(L, idx, "z");
76	        v.z = luaL_optnumber(L, -1, 0.0);
77	        lua_pop(L, 1);
78	    }
79	    else if (lua_isuserdata(L, idx))
80	    {
81	        /* Fast path — userdata backing */
82	        vec3_t *u = (vec3_t *)luaL_checkudata(L, idx, LUA_VEC_METATABLE);
83	        v = *u;
84	    }
85	    else
86	    {
87	        luaL_error(L, "expected vec3 table or userdata at arg #%d", idx);
88	    }
89	
90	    return v;
91	}
