139	/*
140	 * reflect(incident, normal) -> reflected_vec
141	 *   Computes the reflection of an incident vector I about a surface normal N.
142	 *   All vectors are automatically normalized; the returned vector has unit
143	 *   length unless normal is near-zero.
144	 */
145	static int l_reflect(lua_State *L)
146	{
147	    vec3_t I = vec3_normalize(check_vec3(L, 1));
148	    vec3_t N = vec3_normalize(check_vec3(L, 2));
149	
150	    double dotIN = vec3_dot(I, N);
151	    vec3_t R = vec3_sub(I, vec3_scale(N, 2.0 * dotIN));
152	
153	    push_vec3(L, R);
154	    return 1;
155	}
