157	/*
158	 * refract(incident, normal, n1, n2) -> refracted_vec | nil, "TIR"
159	 *   Snell's law refraction.  Returns nil + msg when Total Internal Reflection.
160	 */
161	static int l_refract(lua_State *L)
162	{
163	    vec3_t I  = vec3_normalize(check_vec3(L, 1));
164	    vec3_t N  = vec3_normalize(check_vec3(L, 2));
165	    double n1 = luaL_checknumber(L, 3);
166	    double n2 = luaL_checknumber(L, 4);
167	
168	    double eta = n1 / n2;
169	    double cos_i = -vec3_dot(N, I);
170	    double k = 1.0 - eta * eta * (1.0 - cos_i * cos_i);
171	
172	    if (k < 0.0)
173	    {
174	        lua_pushnil(L);
175	        lua_pushstring(L, "total_internal_reflection");
176	        return 2;
177	    }
178	
179	    vec3_t R = vec3_add(vec3_scale(I, eta),
180	                        vec3_scale(N, (eta * cos_i - sqrt(k))));
181	    push_vec3(L, R);
182	    return 1;
183	}
