185	/*
186	 * fresnel(n1, n2, cos_i) -> reflectance (0..1)
187	 *   Computes unpolarized reflectance using Schlick's approximation.
188	 */
189	static int l_fresnel(lua_State *L)
190	{
191	    double n1    = luaL_checknumber(L, 1);
192	    double n2    = luaL_checknumber(L, 2);
193	    double cos_i = luaL_checknumber(L, 3);
194	
195	    /* Clamp cos_i to [0,1] for numeric stability */
196	    if (cos_i < 0.0) cos_i = 0.0;
197	    if (cos_i > 1.0) cos_i = 1.0;
198	
199	    double r0 = (n1 - n2) / (n1 + n2);
200	    r0 = r0 * r0;
201	    double reflectance = r0 + (1.0 - r0) * pow(1.0 - cos_i, 5.0);
202	
203	    lua_pushnumber(L, reflectance);
204	    return 1;
205	}
