207	/*
208	 * lerp(a, b, t) -> interpolated_value
209	 *   Linear interpolation.  'a' and 'b' may be numbers or vec3 tables.
210	 */
211	static int l_lerp(lua_State *L)
212	{
213	    int type_a = lua_type(L, 1);
214	    int type_b = lua_type(L, 2);
215	    double t   = luaL_checknumber(L, 3);
216	
217	    if (type_a != type_b)
218	        return luaL_error(L, "lerp type mismatch");
219	
220	    if (type_a == LUA_TNUMBER)
221	    {
222	        double a = lua_tonumber(L, 1);
223	        double b = lua_tonumber(L, 2);
224	        lua_pushnumber(L, a + (b - a) * t);
225	        return 1;
226	    }
227	    else if (type_a == LUA_TTABLE || type_a == LUA_TUSERDATA)
228	    {
229	        vec3_t a = check_vec3(L, 1);
230	        vec3_t b = check_vec3(L, 2);
231	        vec3_t r = {
232	            a.x + (b.x - a.x) * t,
233	            a.y + (b.y - a.y) * t,
234	            a.z + (b.z - a.z) * t
235	        };
236	        push_vec3(L, r);
237	        return 1;
238	    }
239	
240	    return luaL_error(L, "unsupported type for lerp");
241	}
