56	/* Read an entire text file into a NUL-terminated buffer.
57	 * Caller owns the *out pointer and must free() it. */
58	static bool
59	read_entire_file(const char *path, char **out, size_t *out_len)
60	{
61	    FILE *fp = fopen(path, "rb");
62	    if (!fp) {
63	        return false;
64	    }
65	
66	    if (fseek(fp, 0, SEEK_END) != 0) {
67	        fclose(fp);
68	        return false;
69	    }
70	
71	    long sz = ftell(fp);
72	    if (sz < 0) {
73	        fclose(fp);
74	        return false;
75	    }
76	    rewind(fp);
77	
78	    char *buf = (char *)malloc((size_t)sz + 1);
79	    if (!buf) {
80	        fclose(fp);
81	        return false;
82	    }
83	
84	    size_t read_sz = fread(buf, 1, (size_t)sz, fp);
85	    fclose(fp);
86	
87	    if (read_sz != (size_t)sz) {
88	        free(buf);
89	        return false;
90	    }
91	
92	    buf[sz] = '\0';                 /* NUL-terminate */
93	    if (out)      *out = buf;
94	    if (out_len)  *out_len = (size_t)sz;
95	    return true;
96	}
