99	/* Convert a cJSON array of two numbers into a float[2] vector.
100	 * Returns false on schema violation. */
101	static bool
102	json_read_vec2(const cJSON *array, float out[2])
103	{
104	    if (!cJSON_IsArray(array) || cJSON_GetArraySize(array) != 2)
105	        return false;
106	
107	    cJSON *x = cJSON_GetArrayItem(array, 0);
108	    cJSON *y = cJSON_GetArrayItem(array, 1);
109	
110	    if (!cJSON_IsNumber(x) || !cJSON_IsNumber(y))
111	        return false;
112	
113	    out[0] = (float)x->valuedouble;
114	    out[1] = (float)y->valuedouble;
115	    return true;
116	}
