160	/* -------------------------------------------------------------------------
161	 * Implementation — parse & create ECS objects
162	 * ------------------------------------------------------------------------- */
163	
164	/* For brevity we use trivially-typed component creation helpers here.     */
165	/* In the real codebase those would be delegated to typed factories.       */
166	
167	typedef struct
168	{
169	    char   id      [64];
170	    char   prefab  [128];
171	    float  pos     [2];
172	    float  rot_deg;
173	    float  mass;
174	    float  velocity[2];
175	    float  wavelength_nm;
176	    float  reflectivity;
177	} EntityBlueprint;
178	
179	
180	static bool
181	parse_entity_blueprint(const cJSON *json, EntityBlueprint *out_bp)
182	{
183	    /* Required fields: id, prefab, initial_position */
184	    const cJSON *id   = cJSON_GetObjectItem(json, "id");
185	    const cJSON *pref = cJSON_GetObjectItem(json, "prefab");
186	    const cJSON *pos  = cJSON_GetObjectItem(json, "initial_position");
187	
188	    if (!cJSON_IsString(id)  ||
189	        !cJSON_IsString(pref)||
190	        !json_read_vec2(pos, out_bp->pos)) {
191	        LOG_ERROR("Entity missing required fields.");
192	        return false;
193	    }
194	
195	    /* Copy strings safely */
196	    strncpy(out_bp->id,    id->valuestring,   sizeof(out_bp->id)   - 1);
197	    strncpy(out_bp->prefab,pref->valuestring, sizeof(out_bp->prefab)-1);
198	
199	    /* Optional fields */
200	    const cJSON *rot = cJSON_GetObjectItem(json, "rotation_deg");
201	    out_bp->rot_deg = cJSON_IsNumber(rot) ? (float)rot->valuedouble : 0.f;
202	
203	    /* Components block is optional but recommended. */
204	    const cJSON *comps  = cJSON_GetObjectItem(json, "components");
205	    if (cJSON_IsObject(comps)) {
206	        const cJSON *physics = cJSON_GetObjectItem(comps, "Physics");
207	        if (cJSON_IsObject(physics)) {
208	            const cJSON *mass = cJSON_GetObjectItem(physics, "mass");
209	            out_bp->mass = cJSON_IsNumber(mass) ? (float)mass->valuedouble : 0.f;
210	
211	            const cJSON *vel  = cJSON_GetObjectItem(physics, "velocity");
212	            if (!json_read_vec2(vel, out_bp->velocity))
213	                out_bp->velocity[0] = out_bp->velocity[1] = 0.f;
214	        }
215	
216	        const cJSON *optics = cJSON_GetObjectItem(comps, "Optics");
217	        if (cJSON_IsObject(optics)) {
218	            const cJSON *wl = cJSON_GetObjectItem(optics, "wavelength");
219	            out_bp->wavelength_nm = cJSON_IsNumber(wl) ?
220	                                      (float)(wl->valuedouble * 1e9) : 0.f;
221	
222	            const cJSON *refl = cJSON_GetObjectItem(optics, "reflectivity");
223	            out_bp->reflectivity = cJSON_IsNumber(refl) ?
224	                                      (float)refl->valuedouble : 0.f;
225	        }
226	    }
227	
228	    return true;
229	}
