232	/* Instantiate entities from blueprints and push them to ECS world.
233	 * This is highly engine-specific; here we stub out the required calls.    */
234	static bool
235	instantiate_entities(ResourceManager  *rm,
236	                     const cJSON      *entities_array)
237	{
238	#ifdef Q4Q_ENGINE_BUILD
239	    ECS_World *world = ecs_world_get_default();
240	#endif
241	
242	    const int count = cJSON_GetArraySize(entities_array);
243	    for (int i = 0; i < count; ++i) {
244	        EntityBlueprint bp = {0};
245	        if (!parse_entity_blueprint(cJSON_GetArrayItem(entities_array, i),
246	                                    &bp))
247	            return false;
248	
249	#ifdef Q4Q_ENGINE_BUILD
250	        /* (1) Obtain a fresh entity ID */
251	        entity_t e = ecs_world_create_entity(world, bp.id);
252	
253	        /* (2) Attach prefab-specific visual/logic components */
254	        attach_prefab_components(world, e, bp.prefab);
255	
256	        /* (3) Override with per-instance data */
257	        cmp_Transform *t = ecs_get_component(world, e, CMP_TRANSFORM);
258	        t->pos.x  = bp.pos[0];
259	        t->pos.y  = bp.pos[1];
260	        t->rot    = bp.rot_deg * (float)M_PI / 180.f;
261	
262	        if (bp.mass > 0.f) {
263	            cmp_Physics *p = ecs_get_or_add_component(world, e, CMP_PHYSICS);
264	            p->mass     = bp.mass;
265	            p->velocity = (vec2){ bp.velocity[0], bp.velocity[1] };
266	        }
267	
268	        if (bp.wavelength_nm > 0.f || bp.reflectivity > 0.f) {
269	            cmp_Optics *o = ecs_get_or_add_component(world, e, CMP_OPTICS);
270	            if (bp.wavelength_nm > 0.f)
271	                o->wavelength_nm = bp.wavelength_nm;
272	            if (bp.reflectivity > 0.f)
273	                o->reflectivity  = bp.reflectivity;
274	        }
275	#else
276	        /* Stand-alone build: just print what we would do. */
277	        LOG_INFO("Instantiating entity '%s' at (%.2f, %.2f) "
278	                 "rot=%.1f° prefab=%s",
279	                 bp.id, bp.pos[0], bp.pos[1], bp.rot_deg, bp.prefab);
280	#endif
281	    }
282	    return true;
283	}
