286	/* Parse the whole level JSON and push it into the resource manager. */
287	static bool
288	register_level_01_basics(ResourceManager *rm, const char *json_source)
289	{
290	    cJSON *root = cJSON_Parse(json_source);
291	    if (!root) {
292	        const char *err = cJSON_GetErrorPtr();
293	        LOG_ERROR("Level 01 Basics: JSON parse error near '%s'.", err);
294	        return false;
295	    }
296	
297	    /* Basic schema validation */
298	    const cJSON *name = cJSON_GetObjectItem(root, "level_name");
299	    const cJSON *dim  = cJSON_GetObjectItem(root, "dimensions");
300	    const cJSON *ents = cJSON_GetObjectItem(root, "entities");
301	
302	    if (!cJSON_IsString(name)  ||
303	        !json_read_vec2(dim, (float[2]){0}) ||
304	        !cJSON_IsArray(ents)) {
305	        LOG_ERROR("Level 01 Basics: missing or invalid root fields.");
306	        cJSON_Delete(root);
307	        return false;
308	    }
309	
310	    /* Push entities to ECS world */
311	    if (!instantiate_entities(rm, ents)) {
312	        LOG_ERROR("Level 01 Basics: failed to instantiate entities.");
313	        cJSON_Delete(root);
314	        return false;
315	    }
316	
317	#ifdef Q4Q_ENGINE_BUILD
318	    /* Register the Level resource so other systems (UI, loading screen,
319	     * scripting engine…) can look it up by handle.                     */
320	    LevelHandle h = resource_manager_add_level(rm,
321	                                               name->valuestring,
322	                                               root /* ownership transferred */);
323	    if (!h) {
324	        LOG_ERROR("Level 01 Basics: could not register resource.");
325	        cJSON_Delete(root);
326	        return false;
327	    }
328	#else
329	    /* Stand-alone build: simply discard the root. */
330	    cJSON_Delete(root);
331	#endif
332	
333	    LOG_INFO("Level 01 Basics registered successfully.");
334	    return true;
335	}
