1	#ifndef QUEST_FOR_QUANTUM_COMMAND_QUEUE_H
2	#define QUEST_FOR_QUANTUM_COMMAND_QUEUE_H
3	/*
4	------------------------------------------------------------------------------
5	Quest for Quantum – Command Queue
6	------------------------------------------------------------------------------
7	An event-driven FIFO that implements the Command Pattern.  Every in-game event
8	(key-presses, physics triggers, AI decisions, timeline cues, etc.) is wrapped
9	in a Command object and dispatched through this queue.
10	
11	Design goals
12	  • Lock-free on the hot path (single producer / single consumer assumption)
13	  • Payload-agnostic – callers own their data via “payload” + destructor
14	  • Optional delayed execution (execute_after_ms)
15	  • Header-only; define CQ_IMPLEMENTATION in *one* .c/.cpp file to emit code
16	  • Minimal dependencies, strictly C11
17	------------------------------------------------------------------------------
18	Copyright © 2024 Quest for Quantum
19	Licensed under MIT – see LICENSE.md
20	------------------------------------------------------------------------------
21	*/
22	
23	#include <stdbool.h>
24	#include <stddef.h>
25	#include <stdint.h>
26	
27	#ifdef __cplusplus
28	extern "C" {
29	#endif
30	
31	/* --------------------------------------------------------------------------
32	 * Public types
33	 * --------------------------------------------------------------------------*/
34	
35	/* Milliseconds since engine boot (consistent with internal clock) */
36	typedef uint64_t cq_time_ms;
37	
38	/* High-level classification of commands.  Extend as needed. */
39	typedef enum
40	{
41	    CQ_CMD_NOP = 0,
42	
43	    /* Input ----------------------------------------------------------------*/
44	    CQ_CMD_INPUT_KEY,        /* keyboard key */
45	    CQ_CMD_INPUT_MOUSE,      /* mouse button / move */
46	    CQ_CMD_INPUT_GAMEPAD,    /* gamepad axis / button */
47	
48	    /* Entity management ----------------------------------------------------*/
49	    CQ_CMD_ENTITY_SPAWN,
50	    CQ_CMD_ENTITY_DESTROY,
51	
52	    /* Simulation specific --------------------------------------------------*/
53	    CQ_CMD_PHYSICS_IMPULSE,
54	    CQ_CMD_OPTICS_COLLISION,
55	    CQ_CMD_AUDIO_PLAY,
56	
57	    /* Scripting ------------------------------------------------------------*/
58	    CQ_CMD_SCRIPT_CALLBACK,
59	
60	    /* Reserved range for user extensions (>= 0x10000) ----------------------*/
61	    CQ_CMD_USER_BEGIN = 0x10000U
62	
63	} CQ_CommandType;
64	
65	/* Forward declaration to let payload callbacks refer to Command */
66	struct CQ_Command;
67	
68	/*
69	 * Callback signature:
70	 *   cmd        – pointer to the command being executed
71	 *   user_data  – generic pointer forwarded by cq_process()
72	 *
73	 * NOTE: The callback *must not* mutate the queue – push/pop is undefined
74	 *       while inside cq_process().
75	 */
76	typedef void (*cq_execute_fn)(struct CQ_Command* cmd, void* user_data);
77	
78	/*
79	 * Optional destructor for payload.  Invoked automatically when the command
80	 * object is freed (either consumed or flushed).
81	 */
82	typedef void (*cq_destroy_payload_fn)(void* payload);
83	
84	/* The Command object itself */
85	typedef struct CQ_Command
86	{
87	    CQ_CommandType          type;               /* classification              */
88	    cq_time_ms              timestamp_ms;       /* enqueue time                */
89	    cq_time_ms              execute_after_ms;   /* delay relative to ts        */
90	
91	    /* Execution hook -------------------------------------------------------*/
92	    cq_execute_fn           execute;            /* may be NULL for passive cmd */
93	
94	    /* User payload ---------------------------------------------------------*/
95	    void*                   payload;            /* arbitrary user data         */
96	    cq_destroy_payload_fn   destroy_payload;    /* destructor can be NULL      */
97	
98	} CQ_Command;
99	
100	/* Single-linked node wrapper used by the queue */
101	typedef struct CQ_Node
102	{
103	    CQ_Command  cmd;
104	    struct CQ_Node* next;
105	} CQ_Node;
106	
107	/*
108	 * The queue itself.  NOT thread-safe by default.  Guard from concurrent
109	 * producers/consumers with external synchronization if needed.
110	 */
111	typedef struct
112	{
113	    CQ_Node* head;      /* pop from here                */
114	    CQ_Node* tail;      /* push to here                 */
115	    size_t   size;      /* number of elements           */
116	    bool     locked;    /* re-entrancy guard (processing)*/
117	} CQ_CommandQueue;
118	
119	/* --------------------------------------------------------------------------
120	 * API
121	 * --------------------------------------------------------------------------*/
122	
123	/* Initialize (or reinitialize after destroy).  Returns true on success. */
124	bool cq_init(CQ_CommandQueue* q);
125	
126	/* Release all resources and reset to zeroed state. */
127	void cq_destroy(CQ_CommandQueue* q);
128	
129	/*
130	 * Enqueue an *existing* command object (deep copy).  The original is left
131	 * untouched.  Returns false on OOM or if queue is locked.
132	 */
133	bool cq_push(CQ_CommandQueue* q, const CQ_Command* cmd);
134	
135	/*
136	 * Convenience helper – construct and push in one call.
137	 *
138	 * type         – command classification
139	 * delay_ms     – delay before eligible for execution (0 = immediate)
140	 * exec         – callback (may be NULL)
141	 * payload      – user-owned pointer (may be NULL)
142	 * dtor         – destructor for payload (may be NULL)
143	 */
144	bool cq_push_copy(CQ_CommandQueue*       q,
145	                  CQ_CommandType         type,
146	                  cq_time_ms             delay_ms,
147	                  cq_execute_fn          exec,
148	                  void*                  payload,
149	                  cq_destroy_payload_fn  dtor);
150	
151	/*
152	 * Pop head into out_cmd.
153	 * Returns false if empty.
154	 */
155	bool cq_pop(CQ_CommandQueue* q, CQ_Command* out_cmd);
156	
157	/* Peek head without removing.  Returns false if empty. */
158	bool cq_peek(const CQ_CommandQueue* q, CQ_Command* out_cmd);
159	
160	/* Return number of queued commands */
161	static inline size_t cq_size(const CQ_CommandQueue* q)
162	{
163	    return q ? q->size : 0U;
164	}
165	
166	/* Fast empty check */
167	static inline bool cq_is_empty(const CQ_CommandQueue* q)
168	{
169	    return (!q) || (q->size == 0U);
170	}
171	
172	/* Remove *all* commands, invoking destructors where appropriate */
173	void cq_flush(CQ_CommandQueue* q);
174	
175	/*
176	 * Process queue:
177	 *   • Executes eligible commands ( current_time_ms >= ts + delay )
178	 *   • Invokes each command's execute() callback
179	 *   • Removes executed commands from the queue
180	 *
181	 * user_data is forwarded verbatim to every callback.
182	 *
183	 * SAFE-GUARDS:
184	 *   – Re-entrancy: queue is locked during processing (push/pop will fail)
185	 *   – Commands may enqueue new commands (push) once processing returns
186	 */
187	void cq_process(CQ_CommandQueue* q,
188	                cq_time_ms       current_time_ms,
189	                void*            user_data);
190	
191	/* --------------------------------------------------------------------------
192	 * Optional iterator (define CQ_ENABLE_ITERATORS before including)
193	 * --------------------------------------------------------------------------*/
194	#ifdef CQ_ENABLE_ITERATORS
195	typedef struct
196	{
197	    const CQ_CommandQueue* queue;
198	    const CQ_Node*         cur;
199	} CQ_Iterator;
200	
201	static inline void cq_iter_begin(const CQ_CommandQueue* q, CQ_Iterator* it)
202	{
203	    it->queue = q;
204	    it->cur   = q ? q->head : NULL;
205	}
206	static inline bool cq_iter_next(CQ_Iterator* it, const CQ_Command** out_cmd)
207	{
208	    if (!it || !out_cmd || !it->cur) return false;
209	    *out_cmd = &it->cur->cmd;
210	    it->cur  = it->cur->next;
211	    return true;
212	}
213	#endif /* CQ_ENABLE_ITERATORS */
214	
215	/* --------------------------------------------------------------------------
216	 * Implementation – define CQ_IMPLEMENTATION exactly *once* in a .c file
217	 * --------------------------------------------------------------------------*/
218	#ifdef CQ_IMPLEMENTATION
219	
220	#include <stdlib.h> /* malloc, free */
221	
222	/* Internal helper – allocates node, deep-copies cmd */
223	static CQ_Node* cq__alloc_node(const CQ_Command* cmd_in)
224	{
225	    CQ_Node* n = (CQ_Node*)malloc(sizeof(CQ_Node));
226	    if (!n) return NULL;
227	
228	    /* Shallow copy of the command */
229	    n->cmd = *cmd_in;
230	    n->next = NULL;
231	    return n;
232	}
233	
234	bool cq_init(CQ_CommandQueue* q)
235	{
236	    if (!q) return false;
237	    q->head   = NULL;
238	    q->tail   = NULL;
239	    q->size   = 0U;
240	    q->locked = false;
241	    return true;
242	}
243	
244	void cq_destroy(CQ_CommandQueue* q)
245	{
246	    if (!q) return;
247	    cq_flush(q);
248	    /* Reset to known state */
249	    q->head   = NULL;
250	    q->tail   = NULL;
251	    q->size   = 0U;
252	    q->locked = false;
253	}
254	
255	bool cq_push(CQ_CommandQueue* q, const CQ_Command* cmd)
256	{
257	    if (!q || !cmd || q->locked) return false;
258	
259	    CQ_Node* node = cq__alloc_node(cmd);
260	    if (!node) return false; /* OOM */
261	
262	    if (!q->tail) /* empty */
263	    {
264	        q->head = q->tail = node;
265	    }
266	    else
267	    {
268	        q->tail->next = node;
269	        q->tail       = node;
270	    }
271	    ++q->size;
272	    return true;
273	}
274	
275	bool cq_push_copy(CQ_CommandQueue*       q,
276	                  CQ_CommandType         type,
277	                  cq_time_ms             delay_ms,
278	                  cq_execute_fn          exec,
279	                  void*                  payload,
280	                  cq_destroy_payload_fn  dtor)
281	{
282	    CQ_Command cmd = {
283	        .type             = type,
284	        .timestamp_ms     = 0,               /* to be set by caller if needed */
285	        .execute_after_ms = delay_ms,
286	        .execute          = exec,
287	        .payload          = payload,
288	        .destroy_payload  = dtor
289	    };
290	    return cq_push(q, &cmd);
291	}
292	
293	bool cq_pop(CQ_CommandQueue* q, CQ_Command* out_cmd)
294	{
295	    if (!q || !out_cmd || cq_is_empty(q) || q->locked) return false;
296	
297	    CQ_Node* node = q->head;
298	    *out_cmd      = node->cmd;
299	
300	    q->head = node->next;
301	    if (!q->head) q->tail = NULL;
302	    --q->size;
303	
304	    free(node);
305	    return true;
306	}
307	
308	bool cq_peek(const CQ_CommandQueue* q, CQ_Command* out_cmd)
309	{
310	    if (!q || !out_cmd || cq_is_empty(q)) return false;
311	    *out_cmd = q->head->cmd;
312	    return true;
313	}
314	
315	void cq_flush(CQ_CommandQueue* q)
316	{
317	    if (!q) return;
318	
319	    q->locked = true; /* inhibit recursive push/pop during flush */
320	
321	    CQ_Node* node = q->head;
322	    while (node)
323	    {
324	        CQ_Node* next = node->next;
325	
326	        /* Destroy payload if requested */
327	        if (node->cmd.destroy_payload && node->cmd.payload)
328	            node->cmd.destroy_payload(node->cmd.payload);
329	
330	        free(node);
331	        node = next;
332	    }
333	
334	    q->head = q->tail = NULL;
335	    q->size = 0U;
336	    q->locked = false;
337	}
338	
339	void cq_process(CQ_CommandQueue* q,
340	                cq_time_ms       current_time_ms,
341	                void*            user_data)
342	{
343	    if (!q) return;
344	
345	    /* Early out if queue empty */
346	    if (cq_is_empty(q)) return;
347	
348	    q->locked = true;
349	
350	    /* iterate list, executing & removing eligible commands */
351	    CQ_Node*  prev = NULL;
352	    CQ_Node*  node = q->head;
353	
354	    while (node)
355	    {
356	        bool eligible = (current_time_ms >=
357	                        (node->cmd.timestamp_ms + node->cmd.execute_after_ms));
358	
359	        /* Next pointer kept because node may be freed */
360	        CQ_Node* next = node->next;
361	
362	        if (eligible)
363	        {
364	            /* Execute callback if provided */
365	            if (node->cmd.execute)
366	                node->cmd.execute(&node->cmd, user_data);
367	
368	            /* Destroy payload */
369	            if (node->cmd.destroy_payload && node->cmd.payload)
370	                node->cmd.destroy_payload(node->cmd.payload);
371	
372	            /* Remove node from list ---------------------------------------*/
373	            if (prev)
374	                prev->next = next;
375	            else
376	                q->head = next;
377	
378	            if (node == q->tail)
379	                q->tail = prev;
380	
381	            free(node);
382	            --q->size;
383	        }
384	        else
385	        {
386	            /* Not yet eligible – maintain ordering (FIFO) */
387	            prev = node;
388	        }
389	
390	        node = next;
391	    }
392	
393	    q->locked = false;
394	}
395	
396	#endif /* CQ_IMPLEMENTATION */
397	
398	#ifdef __cplusplus
399	} /* extern "C" */
400	#endif
