1	/**
2	 * Quest for Quantum: Resource Manager
3	 *
4	 * A header-only, production-quality resource manager that supports:
5	 *  • Centralised lifetime tracking (retain / release semantics)
6	 *  • Hot-loading & event dispatching on file changes
7	 *  • Synchronous and asynchronous load APIs
8	 *  • Thread-safe retrieval
9	 *  • Optional implementation (define RESOURCE_MANAGER_IMPLEMENTATION
10	 *    in exactly ONE compilation unit before including this file)
11	 *
12	 * This manager is intentionally focused on *runtime* assets—textures,
13	 * audio buffers, level JSON, and teacher scripts.  Science data (e.g.,
14	 * wavelength tables) is handled elsewhere.
15	 *
16	 * Usage:
17	 *
18	 *      #define RESOURCE_MANAGER_IMPLEMENTATION
19	 *      #include "resource/resource_manager.h"
20	 *
21	 *      struct EventBus bus = { ... };
22	 *      if (!rm_init("./assets", &bus, 64 * 1024 * 1024))
23	 *              fprintf(stderr, "RM init failed\n");
24	 *
25	 *      RmHandle tex = rm_load_sync(RM_TYPE_TEXTURE, "sprites/photon.png");
26	 *      const struct RmTexture *t = rm_texture(tex);
27	 *
28	 *      rm_release(tex);   // balanced with load / retain
29	 *      rm_shutdown();
30	 *
31	 *  Threading:
32	 *      Internally a small job queue + worker thread is spun up for async
33	 *      requests.  API calls that *inspect* resources are lock-free after the
34	 *      first load (read-only); mutating calls are protected by a spin-lock.
35	 */
36	
37	#ifndef QUEST_FOR_QUANTUM_RESOURCE_MANAGER_H
38	#define QUEST_FOR_QUANTUM_RESOURCE_MANAGER_H
39	#pragma once
40	
41	/* ------------------------------------------------------------- */
42	/*  Public interface                                              */
43	/* ------------------------------------------------------------- */
44	
45	#include <stddef.h>
46	#include <stdint.h>
47	#include <stdbool.h>
48	
49	#ifdef __cplusplus
50	extern "C" {
51	#endif
52	
53	/* --------- Forward declarations to avoid heavy headers -------- */
54	struct EventBus;          /* Command/Observer bus (core)      */
55	struct SDL_Renderer;      /* SDL2 renderer                    */
56	struct SDL_Texture;       /* SDL2 texture object              */
57	struct Mix_Chunk;         /* SDL_mixer audio buffer           */
58	
59	/* -------------------------------------------------------------- */
60	/*  Resource Typedefs                                             */
61	/* -------------------------------------------------------------- */
62	
63	/* Strongly-typed 32-bit handle */
64	typedef struct { uint32_t id; } RmHandle;
65	#define RM_NULL_HANDLE (RmHandle){0}
66	
67	static inline bool rm_handle_valid(RmHandle h) { return h.id != 0; }
68	
69	/* Enumerate asset classes supported by the manager */
70	typedef enum RmType {
71	    RM_TYPE_UNKNOWN  = 0,
72	    RM_TYPE_TEXTURE  = 1,
73	    RM_TYPE_AUDIO    = 2,
74	    RM_TYPE_SCRIPT   = 3,
75	    RM_TYPE_LEVEL    = 4,
76	    RM_TYPE_BINARY   = 5,
77	    RM_TYPE_COUNT
78	} RmType;
79	
