263	/* -------- Spinlock (C11 mtx_t is heavy for quick ops) ----- */
264	typedef struct RmSpin {
265	    atomic_flag flag;
266	} RmSpin;
267	
268	static inline void spin_init(RmSpin *s) { atomic_flag_clear(&s->flag); }
269	static inline void spin_lock(RmSpin *s) { while (atomic_flag_test_and_set_explicit(&s->flag, memory_order_acquire)) { /* busy */ } }
270	static inline void spin_unlock(RmSpin *s){ atomic_flag_clear_explicit(&s->flag, memory_order_release); }
