272	/* -------- Simple open-addressing handle table ------------- */
273	typedef struct RmSlot {
274	    RmResource *ptr;     /* NULL if slot free */
275	} RmSlot;
276	
277	static struct {
278	    bool            init_done;
279	    char           *asset_root;
280	    size_t          asset_root_len;
281	    size_t          memory_budget;
282	    size_t          memory_used;
283	
284	    RmSlot          table[RM_MAX_RESOURCES];
285	
286	    /* hashtable path->handle (very small, string keys) */
287	    struct {
288	        char     **keys;
289	        RmHandle  *values;
290	        size_t     capacity;
291	        size_t     count;
292	    } lookup;
293	
294	    /* Threading */
295	    thrd_t          worker;
296	    mtx_t           job_lock;
297	    cnd_t           job_cv;
298	    struct RmJob   *job_head;
299	    struct RmJob   *job_tail;
300	    bool            worker_exit;
301	
302	    /* Daisy-chained hot reload listener list */
303	    struct RmListener {
304	        RmHandle               handle;
305	        RmHotReloadCallback    cb;
306	        void                  *user;
307	        struct RmListener     *next;
308	    } *listeners;
309	
310	    /* External systems */
311	    struct EventBus *bus;
312	} g_rm;
