314	/* ----------------------------------------------------------- */
315	/*        Helper: allocate / index handles                     */
316	/* ----------------------------------------------------------- */
317	static RmHandle make_handle(uint32_t idx)
318	{
319	    return (RmHandle){ .id = idx + 1 };  /* 0 reserved */
320	}
321	
322	static uint32_t handle_index(RmHandle h)
323	{
324	    return h.id - 1;
325	}
326	
327	static RmResource *resource_from_handle(RmHandle h)
328	{
329	    if (!rm_handle_valid(h)) return NULL;
330	    uint32_t i = handle_index(h);
331	    if (i >= RM_MAX_RESOURCES) return NULL;
332	    return g_rm.table[i].ptr;
333	}
334	
335	/* Allocate slot for new resource, returns handle or NULL_HANDLE */
336	static RmHandle alloc_slot(RmResource *ptr)
337	{
338	    for (uint32_t i = 0; i < RM_MAX_RESOURCES; ++i) {
339	        if (!g_rm.table[i].ptr) {
340	            g_rm.table[i].ptr = ptr;
341	            return make_handle(i);
342	        }
343	    }
344	    return RM_NULL_HANDLE;
345	}
346	
347	/* Free slot */
348	static void free_slot(RmHandle h)
349	{
350	    uint32_t idx = handle_index(h);
351	    g_rm.table[idx].ptr = NULL;
352	}
353	
354	/* ----------------------------------------------------------- */
355	/*       String table (very light)                             */
356	/* ----------------------------------------------------------- */
357	static void lt_init(size_t reserve)
358	{
359	    g_rm.lookup.capacity = reserve;
360	    g_rm.lookup.keys     = calloc(reserve, sizeof(char *));
361	    g_rm.lookup.values   = calloc(reserve, sizeof(RmHandle));
362	}
363	
364	static size_t lt_hash(const char *s)
365	{
366	    /* FNV-1a */
367	    uint32_t h = 2166136261u;
368	    for (; *s; ++s) {
369	        h ^= (uint8_t)*s;
370	        h *= 16777619u;
371	    }
372	    return h;
373	}
374	
375	static size_t lt_probe(const char *key)
376	{
377	    size_t mask = g_rm.lookup.capacity - 1;
378	    size_t idx = lt_hash(key) & mask;
379	    while (1) {
380	        if (!g_rm.lookup.keys[idx]) return idx;
381	        if (strcmp(g_rm.lookup.keys[idx], key) == 0) return idx;
382	        idx = (idx + 1) & mask;
383	    }
384	}
385	
386	static void lt_put(const char *key, RmHandle val)
387	{
388	    if (g_rm.lookup.count * 2 >= g_rm.lookup.capacity) {
389	        /* TODO: grow (not needed for small counts) */
390	    }
391	    size_t idx = lt_probe(key);
392	    if (!g_rm.lookup.keys[idx]) {
393	        g_rm.lookup.keys[idx] = strdup(key);
394	        ++g_rm.lookup.count;
395	    }
396	    g_rm.lookup.values[idx] = val;
397	}
398	
399	static RmHandle lt_get(const char *key)
400	{
401	    if (!g_rm.lookup.capacity) return RM_NULL_HANDLE;
402	    size_t idx = lt_probe(key);
403	    if (!g_rm.lookup.keys[idx]) return RM_NULL_HANDLE;
404	    return g_rm.lookup.values[idx];
405	}
