407	/* ----------------------------------------------------------- */
408	/*    Job system for async loads                               */
409	/* ----------------------------------------------------------- */
410	typedef struct RmJob {
411	    RmType          type;
412	    char           *vpath;
413	    RmLoadCallback  cb;
414	    void           *user;
415	    struct RmJob   *next;
416	} RmJob;
417	
418	static int worker_main(void *arg)
419	{
420	    (void)arg;
421	    while (1) {
422	        mtx_lock(&g_rm.job_lock);
423	        while (!g_rm.job_head && !g_rm.worker_exit) {
424	            cnd_wait(&g_rm.job_cv, &g_rm.job_lock);
425	        }
426	        if (g_rm.worker_exit) {
427	            mtx_unlock(&g_rm.job_lock);
428	            break;
429	        }
430	        RmJob *job = g_rm.job_head;
431	        g_rm.job_head = job->next;
432	        if (!g_rm.job_head) g_rm.job_tail = NULL;
433	        mtx_unlock(&g_rm.job_lock);
434	
435	        /* Execute load in worker thread */
436	        RmError err = RM_OK;
437	        RmHandle h = rm_load_sync(job->type, job->vpath, &err);
438	        /* Notify user */
439	        job->cb(h, err, job->user);
440	        free(job->vpath);
441	        free(job);
442	    }
443	    return 0;
444	}
