449	
450	bool rm_init(const char *asset_root, struct EventBus *bus, size_t budget)
451	{
452	    if (g_rm.init_done) return true;
453	
454	    if (!asset_root) return false;
455	
456	    g_rm.asset_root      = strdup(asset_root);
457	    g_rm.asset_root_len  = strlen(asset_root);
458	    g_rm.memory_budget   = budget;
459	    g_rm.bus             = bus;
460	
461	    memset(g_rm.table, 0, sizeof(g_rm.table));
462	    lt_init(1024);
463	
464	    /* Threading */
465	    mtx_init(&g_rm.job_lock, mtx_plain);
466	    cnd_init(&g_rm.job_cv);
467	    g_rm.worker_exit = false;
468	    if (thrd_create(&g_rm.worker, worker_main, NULL) != thrd_success)
469	        return false;
470	
471	    g_rm.init_done = true;
472	    return true;
473	}
474	
475	void rm_shutdown(void)
476	{
477	    if (!g_rm.init_done) return;
478	
479	    /* Release all resources */
480	    for (uint32_t i = 0; i < RM_MAX_RESOURCES; ++i) {
481	        RmResource *r = g_rm.table[i].ptr;
482	        if (r) {
483	            switch (r->type) {
484	                case RM_TYPE_TEXTURE:
485	                    SDL_DestroyTexture(((RmTexture*)r)->sdl);
486	                    break;
487	                case RM_TYPE_AUDIO:
488	                    Mix_FreeChunk(((RmAudio*)r)->chunk);
489	                    break;
490	                case RM_TYPE_BINARY:
491	                case RM_TYPE_SCRIPT:
492	                case RM_TYPE_LEVEL:
493	                    free(((RmBinary*)r)->bytes);
494	                    break;
495	                default: break;
496	            }
497	            free(r->virtual_path);
498	            free(r);
499	        }
500	    }
501	
502	    /* kill worker */
503	    mtx_lock(&g_rm.job_lock);
504	    g_rm.worker_exit = true;
505	    cnd_signal(&g_rm.job_cv);
506	    mtx_unlock(&g_rm.job_lock);
507	    thrd_join(g_rm.worker, NULL);
508	
509	    free(g_rm.asset_root);
510	
511	    for (size_t i = 0; i < g_rm.lookup.capacity; ++i)
512	        free(g_rm.lookup.keys[i]);
513	    free(g_rm.lookup.keys);
514	    free(g_rm.lookup.values);
515	
516	    mtx_destroy(&g_rm.job_lock);
517	    cnd_destroy(&g_rm.job_cv);
518	
519	    g_rm.init_done = false;
520	}
