522	/* Utility: build absolute path */
523	static char *abs_path(const char *vpath)
524	{
525	    size_t len = g_rm.asset_root_len + 1 + strlen(vpath) + 1;
526	    char *buf = malloc(len);
527	    snprintf(buf, len, "%s/%s", g_rm.asset_root, vpath);
528	    return buf;
529	}
