531	/* Loaders */
532	static RmError load_texture(const char *abs, RmTexture *out)
533	{
534	    SDL_Surface *surf = IMG_Load(abs);
535	    if (!surf) return RM_ERR_IO;
536	    SDL_Renderer *renderer = SDL_GetRenderer(SDL_GetWindowFromID(1));
537	    if (!renderer) { SDL_FreeSurface(surf); return RM_ERR_INTERNAL; }
538	    out->sdl = SDL_CreateTextureFromSurface(renderer, surf);
539	    out->width  = (uint16_t)surf->w;
540	    out->height = (uint16_t)surf->h;
541	    SDL_FreeSurface(surf);
542	    return out->sdl ? RM_OK : RM_ERR_IO;
543	}
544	
545	static RmError load_audio(const char *abs, RmAudio *out)
546	{
547	    out->chunk = Mix_LoadWAV(abs);
548	    if (!out->chunk) return RM_ERR_IO;
549	    out->length = out->chunk->alen;
550	    out->freq   = 44100; /* TODO query real freq */
551	    return RM_OK;
552	}
553	
554	static RmError load_binary(const char *abs, RmBinary *out)
555	{
556	    FILE *fp = fopen(abs, "rb");
557	    if (!fp) return RM_ERR_IO;
558	    fseek(fp, 0, SEEK_END);
559	    long sz = ftell(fp);
560	    fseek(fp, 0, SEEK_SET);
561	    out->bytes = malloc(sz);
562	    if (fread(out->bytes, 1, sz, fp) != (size_t)sz) {
563	        fclose(fp);
564	        free(out->bytes);
565	        return RM_ERR_IO;
566	    }
567	    fclose(fp);
568	    out->size = sz;
569	    return RM_OK;
570	}
