572	/* Generic sync loader */
573	RmHandle rm_load_sync(RmType type, const char *vpath, RmError *err_ret)
574	{
575	    if (!g_rm.init_done || !vpath) {
576	        if (err_ret) *err_ret = RM_ERR_BAD_PARAMS;
577	        return RM_NULL_HANDLE;
578	    }
579	
580	    /* Fast path: already present */
581	    RmHandle existing = lt_get(vpath);
582	    if (rm_handle_valid(existing)) {
583	        rm_retain(existing);
584	        if (err_ret) *err_ret = RM_OK;
585	        return existing;
586	    }
587	
588	    /* Build object depending on type */
589	    RmError err = RM_OK;
590	    RmResource *base = NULL;
591	    char *abs = abs_path(vpath);
592	
593	    switch (type) {
594	        case RM_TYPE_TEXTURE: {
595	            RmTexture *t = calloc(1, sizeof(*t));
596	            t->base.type = type;
597	            if ((err = load_texture(abs, t)) == RM_OK)
598	                base = &t->base;
599	            else
600	                free(t);
601	            break;
602	        }
603	        case RM_TYPE_AUDIO: {
604	            RmAudio *a = calloc(1, sizeof(*a));
605	            a->base.type = type;
606	            if ((err = load_audio(abs, a)) == RM_OK)
607	                base = &a->base;
608	            else
609	                free(a);
610	            break;
611	        }
612	        case RM_TYPE_SCRIPT:
613	        case RM_TYPE_LEVEL:
614	        case RM_TYPE_BINARY: {
615	            RmBinary *b = calloc(1, sizeof(*b));
616	            b->base.type = type;
617	            if ((err = load_binary(abs, b)) == RM_OK)
618	                base = &b->base;
619	            else
620	                free(b);
621	            break;
622	        }
623	        default: err = RM_ERR_UNSUPPORTED; break;
624	    }
625	    free(abs);
626	
627	    if (!base) {
628	        if (err_ret) *err_ret = err;
629	        return RM_NULL_HANDLE;
630	    }
631	
632	    /* Initialise common header */
633	    base->magic = RM_MAGIC;
634	    base->ref_count = 1;
635	    base->virtual_path = strdup(vpath);
636	
637	    /* File timestamp */
638	    struct stat st;
639	    if (stat(abs_path(vpath), &st) == 0)
640	        base->file_timestamp = st.st_mtime;
641	
642	    /* Enter table */
643	    RmHandle h = alloc_slot(base);
644	    if (!rm_handle_valid(h)) {
645	        /* Table full */
646	        /* Clean up */
647	        rm_release(make_handle(0)); /* just to reuse release logic? but h invalid */
648	    }
649	
650	    lt_put(vpath, h);
651	
652	    if (err_ret) *err_ret = err;
653	    return h;
654	}
655	
656	/* Async wrapper */
657	RmHandle rm_load_async(RmType type, const char *vpath,
658	                       RmLoadCallback cb, void *user)
659	{
660	    RmError dummy;
661	    RmHandle existing = rm_load_sync(type, vpath, &dummy);
662	    if (dummy == RM_OK && existing.id && dummy != RM_ERR_IO) {
663	        /* Already loaded, call back immediately on main thread */
664	        if (cb) cb(existing, RM_OK, user);
665	        return existing;
666	    }
667	
668	    /* Schedule job */
669	    RmJob *job = calloc(1, sizeof(*job));
670	    job->type = type;
671	    job->vpath = strdup(vpath);
672	    job->cb = cb;
673	    job->user = user;
674	
675	    mtx_lock(&g_rm.job_lock);
676	    if (g_rm.job_tail)
677	        g_rm.job_tail->next = job;
678	    else
679	        g_rm.job_head = job;
680	    g_rm.job_tail = job;
681	    cnd_signal(&g_rm.job_cv);
682	    mtx_unlock(&g_rm.job_lock);
683	
684	    return RM_NULL_HANDLE; /* provisional */
685	}
