687	/* Retain / Release */
688	void rm_retain(RmHandle h)
689	{
690	    RmResource *r = resource_from_handle(h);
691	    if (r) atomic_fetch_add_explicit((_Atomic uint32_t *)&r->ref_count, 1, memory_order_relaxed);
692	}
693	
694	void rm_release(RmHandle h)
695	{
696	    RmResource *r = resource_from_handle(h);
697	    if (!r) return;
698	    if (atomic_fetch_sub_explicit((_Atomic uint32_t *)&r->ref_count, 1, memory_order_acq_rel) == 1) {
699	        /* free */
700	        switch (r->type) {
701	            case RM_TYPE_TEXTURE:
702	                SDL_DestroyTexture(((RmTexture*)r)->sdl);
703	                break;
704	            case RM_TYPE_AUDIO:
705	                Mix_FreeChunk(((RmAudio*)r)->chunk);
706	                break;
707	            case RM_TYPE_BINARY:
708	            case RM_TYPE_SCRIPT:
709	            case RM_TYPE_LEVEL:
710	                free(((RmBinary*)r)->bytes);
711	                break;
712	            default: break;
713	        }
714	        lt_put(r->virtual_path, RM_NULL_HANDLE); /* remove mapping */
715	        free(r->virtual_path);
716	        free_slot(h);
717	        free(r);
718	    }
719	}
