1	/*
2	 * Quest for Quantum: Resource Hot-Loader
3	 * --------------------------------------
4	 * A lightweight, polling-based hot-loader that detects file changes at run-time
5	 * and notifies the engine so that resources can be refreshed without a restart.
6	 *
7	 * Typical usage:
8	 *
9	 *      #define Q4Q_HOT_LOADER_IMPLEMENTATION
10	 *      #include "resource/hot_loader.h"
11	 *
12	 *      static void on_file_change(const char *path, void *ud)
13	 *      {
14	 *          printf(">>> %s modified, reload!\n", path);
15	 *      }
16	 *
17	 *      int main(void)
18	 *      {
19	 *          HotLoader *hl = hot_loader_create("./assets", 0.5);      // 0.5s poll
20	 *          hot_loader_watch(hl, "textures/wall.png", on_file_change, NULL);
21	 *
22	 *          while (game_is_running()) {
23	 *              hot_loader_update(hl, game_get_delta());
24	 *              ...
25	 *          }
26	 *
27	 *          hot_loader_destroy(hl);
28	 *      }
29	 *
30	 *  The API is intentionally minimal and portable (POSIX + Windows). All code is
31	 *  header-only; simply include the header in exactly ONE translation unit with
32	 *  Q4Q_HOT_LOADER_IMPLEMENTATION defined before the include to generate the
33	 *  implementation.
34	 */
35	
36	#ifndef Q4Q_RESOURCE_HOT_LOADER_H
37	#define Q4Q_RESOURCE_HOT_LOADER_H
38	
39	/*----------------------------------------------------------------------*/
40	/*  Public API                                                          */
41	/*----------------------------------------------------------------------*/
42	
43	#ifdef __cplusplus
44	extern "C" {
45	#endif
