49	/* Directory separator utility                                            */
50	#if defined(_WIN32) || defined(_WIN64)
51	#   define Q4Q_PATH_SEP '\\'
52	#else
53	#   define Q4Q_PATH_SEP '/'
54	#endif
55	
56	/* Opaque hot-loader handle                                               */
57	typedef struct HotLoader HotLoader;
58	
59	/* Callback type executed when a watched file changes                     */
60	typedef void (*HotLoadCallback)(const char *virtual_path, void *user_data);
61	
62	/* Create a new HotLoader.
63	 *  root_directory   : The directory serving as logical root for all watch
64	 *                     paths (e.g., "./assets"). Can be NULL to accept any path.
65	 *  poll_interval_sec: Minimum time (seconds) between successive file system
66	 *                     checks to avoid thrashing the OS.
67	 *  Returns a pointer to the new HotLoader, or NULL on allocation failure.     */
68	HotLoader *hot_loader_create(const char *root_directory, double poll_interval_sec);
69	
70	/* Destroy a HotLoader and release all internal memory.                   */
71	void hot_loader_destroy(HotLoader *loader);
72	
73	/* Begin monitoring the provided file.
74	 *  virtual_path: Path relative to the root_directory specified at create time.
75	 *                May also be absolute if root_directory was NULL.
76	 *  cb          : Callback invoked once the file's last-modified timestamp
77	 *                changes. Executed in the thread that calls hot_loader_update.
78	 *  user_data   : Opaque pointer forwarded to the callback.
79	 *  Returns 0 on success, negative value on error (already watched, not found,
80	 *  memory error, etc.).                                                   */
81	int  hot_loader_watch(HotLoader *loader,
82	                      const char *virtual_path,
83	                      HotLoadCallback cb,
84	                      void *user_data);
85	
86	/* Stop monitoring a path. Has no effect if the file isn't being watched. */
87	void hot_loader_unwatch(HotLoader *loader, const char *virtual_path);
88	
89	/* Call during the main loop. If poll_interval has elapsed, the hot-loader
90	 * probes each watched file and invokes callbacks whose timestamps changed.
91	 *  dt_sec: Delta-time since previous frame, in seconds.                   */
92	void hot_loader_update(HotLoader *loader, double dt_sec);
93	
94	/* Optional helpers                                                       */
95	void hot_loader_pause (HotLoader *loader); /* Temporarily suspend scans   */
96	void hot_loader_resume(HotLoader *loader); /* Resume after pause          */
97	
98	/* Return 1 if the loader is currently paused, 0 otherwise.               */
99	int  hot_loader_is_paused(const HotLoader *loader);
100	
101	/* Set a new polling interval (seconds). Takes effect immediately.        */
102	void hot_loader_set_poll_interval(HotLoader *loader, double interval_sec);
103	
104	/* Retrieve the current polling interval.                                 */
105	double hot_loader_get_poll_interval(const HotLoader *loader);
